head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[tabControl > M > disableTab]<br/>인덱스값을 사용하여 특정 Tab 페이지를 비활성화(disabled)합니다.",
    "validation" : [
        "tabIndex(필수) 파라미터로 비활성화(disabled) 하려는 Tab 페이지의 인덱스값을 숫자로 설정합니다.",
        "Tab 페이지의 인덱스는 0 부터 시작합니다.",
        "Tab 페이지가 비활성화(disabled) 되면 Tab 버튼과 Content 가 모두 비활성화(disabled) 되며 Tab 버튼도 동작하지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정   
    let properties = {
        alwaysDraw : true,
    };

    let cList = $c.gcm.createCList(properties);      
    let eList = $c.gcm.createEList(["onchange"]);

    let grp_comp = $c.gcm.getTestGroup();    
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:tabControl ' + strNameSpace + ' ' + cList + ' ' + eList + ' id="" style="width:500px;height:200px;">';
    strTarget += '<w2:tabs disabled="false" style="height:40px;" id="tabs1" label="Tabs1"></w2:tabs>';
    strTarget += '<w2:tabs disabled="false" style="height:40px" id="tabs2" label="Tabs2"></w2:tabs>';
    strTarget += '<w2:tabs disabled="false" style="height:40px" id="tabs3" label="Tabs3"></w2:tabs>';
    strTarget += '<w2:content style="height:160px;" id="content1">';
    strTarget += '<w2:button style="width:80px; width:130px; height:50px;" id="content1_child" label="content1_child"></w2:button>';
    strTarget += '</w2:content>';
    strTarget += '<w2:content style="height:160px" id="content2">';
    strTarget += '<xf:input id="content2_child" style="width:144px; height:21px; " initValue="content2_child"></xf:input>';
    strTarget += '</w2:content>';
    strTarget += '<w2:content style="height:160px" id="content3">';    
    strTarget += '<w2:textbox id="content3_child" label="content3_child" style="width:200px; height:50px; background-color:var(--ws-gray-300);"></w2:textbox>';
    strTarget += '</w2:content>';
    strTarget += '</w2:tabControl>';

    // target 생성
    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "tabControl",
        strTarget,
        grp_comp
    );
}



scwin.btn_getDisabled_onclick = function (e) {   
    const tabIndexes = [0, 1, 2];

    tabIndexes.forEach(index => {
        let tab = document.querySelector(`li[id*=target1_tab_tabs${index + 1}]`);
        wf_body_bottom.getObj("scwin").setReturnValue(`tabs${index + 1} className : ${tab.className}`);

        let content = document.querySelector(`div[id*=target1_contents_content${index + 1}_body]`);        
        let isDisabled = content.disabled;
        wf_body_bottom.getObj("scwin").setReturnValue(`content${index + 1} disabled : ${isDisabled}`);
    });    
};




scwin.btn_disableTab_onclick = function (e) {
	target1.disableTab(par_tabIndex.getText());

    scwin.btn_getDisabled_onclick();	
};



scwin.target1_onchange = function (tabId, index, userTabId) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onchange=====")
}
